// Procedural isometric wireframes. The same seed always draws the same scene,
// so every project and post gets its own drawing without an image file.

export type Box = { x: number; y: number; w: number; d: number; h: number; lit?: boolean };

export type Scene = {
  viewBox: string;
  grid: string[];
  boxes: { faces: string[]; windows: string[]; lit: boolean; delay: number }[];
};

function hash(text: string): number {
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function random(seed: number): () => number {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const COS = Math.cos(Math.PI / 6);
const SIN = 0.5;

function point(x: number, y: number, z: number, unit: number): [number, number] {
  return [(x - y) * COS * unit, (x + y) * SIN * unit - z * unit];
}

function path(points: [number, number][], close = true): string {
  const d = points.map(([px, py], i) => `${i ? 'L' : 'M'}${px.toFixed(1)} ${py.toFixed(1)}`).join('');
  return close ? `${d}Z` : d;
}

export function scene(seed: string, options: { size?: number; count?: number; tall?: number } = {}): Scene {
  const size = options.size ?? 12;
  const count = options.count ?? 9;
  const tall = options.tall ?? 6;
  const unit = 22;
  const rand = random(hash(seed));

  // Place boxes on a coarse lattice so they never overlap and draw in order.
  const taken = new Set<string>();
  const boxes: Box[] = [];
  let tries = 0;
  while (boxes.length < count && tries < 400) {
    tries++;
    const w = 1 + Math.floor(rand() * 2) * 1 + (rand() > 0.8 ? 1 : 0);
    const d = 1 + Math.floor(rand() * 2) * 1 + (rand() > 0.8 ? 1 : 0);
    const x = 1 + Math.floor(rand() * (size - w - 1));
    const y = 1 + Math.floor(rand() * (size - d - 1));
    let clear = true;
    for (let i = x - 1; i <= x + w && clear; i++) {
      for (let j = y - 1; j <= y + d; j++) {
        if (taken.has(`${i},${j}`)) {
          clear = false;
          break;
        }
      }
    }
    if (!clear) continue;
    for (let i = x; i < x + w; i++) for (let j = y; j < y + d; j++) taken.add(`${i},${j}`);
    const h = 1 + Math.floor(rand() * tall);
    boxes.push({ x, y, w, d, h });
  }
  if (boxes.length) boxes[Math.floor(rand() * boxes.length)].lit = true;
  boxes.sort((a, b) => a.x + a.y + (a.w + a.d) / 2 - (b.x + b.y + (b.w + b.d) / 2));

  const grid: string[] = [];
  for (let i = 0; i <= size; i++) {
    grid.push(path([point(i, 0, 0, unit), point(i, size, 0, unit)], false));
    grid.push(path([point(0, i, 0, unit), point(size, i, 0, unit)], false));
  }

  const drawn = boxes.map((box, index) => {
    const { x, y, w, d, h } = box;
    const top = path([point(x, y, h, unit), point(x + w, y, h, unit), point(x + w, y + d, h, unit), point(x, y + d, h, unit)]);
    const right = path([point(x + w, y, 0, unit), point(x + w, y + d, 0, unit), point(x + w, y + d, h, unit), point(x + w, y, h, unit)]);
    const left = path([point(x, y + d, 0, unit), point(x + w, y + d, 0, unit), point(x + w, y + d, h, unit), point(x, y + d, h, unit)]);
    const windows: string[] = [];
    for (let k = 1; k < h; k++) {
      windows.push(path([point(x + w, y, k, unit), point(x + w, y + d, k, unit)], false));
      windows.push(path([point(x, y + d, k, unit), point(x + w, y + d, k, unit)], false));
    }
    const step = 0.5;
    for (let s = step; s < d - 0.01; s += step) windows.push(path([point(x + w, y + s, 0, unit), point(x + w, y + s, h, unit)], false));
    for (let s = step; s < w - 0.01; s += step) windows.push(path([point(x + s, y + d, 0, unit), point(x + s, y + d, h, unit)], false));
    return { faces: [left, right, top], windows, lit: Boolean(box.lit), delay: index * 90 };
  });

  const [minX] = point(0, size, 0, unit);
  const [maxX] = point(size, 0, 0, unit);
  const top = -tall * unit - unit;
  const [, bottom] = point(size, size, 0, unit);
  const pad = unit;
  const viewBox = `${(minX - pad).toFixed(0)} ${(top - pad).toFixed(0)} ${(maxX - minX + pad * 2).toFixed(0)} ${(bottom - top + pad * 2).toFixed(0)}`;

  return { viewBox, grid, boxes: drawn };
}

// A code-minimap backdrop: rows of "code" whose colours follow the project's
// language mix. Measured languages come from a spec file; otherwise the mix is
// read from the technology list and marked as inferred.

export type LanguageShare = { name: string; share: number; color: string };

const COLORS: Record<string, string> = {
  TypeScript: '#3178c6',
  JavaScript: '#f1e05a',
  PHP: '#777bb4',
  Twig: '#c1d026',
  CSS: '#663399',
  SCSS: '#c6538c',
  HTML: '#e34c26',
  Ruby: '#cc342d',
  Python: '#3572a5',
  SQL: '#e38c00',
  Swift: '#f05138',
  Shell: '#89e051',
  Vue: '#41b883',
  Liquid: '#67b8de',
};

const INFER: [RegExp, Record<string, number>][] = [
  [/wordpress|acf|bedrock/i, { PHP: 5, JavaScript: 2, SCSS: 2, HTML: 1 }],
  [/craft/i, { Twig: 4, PHP: 3, JavaScript: 2, CSS: 1 }],
  [/drupal/i, { PHP: 5, Twig: 2, JavaScript: 2, SCSS: 1 }],
  [/symfony|symphony/i, { PHP: 4, Twig: 1 }],
  [/vue/i, { Vue: 3, JavaScript: 2 }],
  [/react|next|expo/i, { TypeScript: 4, JavaScript: 2, CSS: 1 }],
  [/angular/i, { TypeScript: 5, SCSS: 2, HTML: 2 }],
  [/ruby/i, { Ruby: 4, HTML: 1 }],
  [/python/i, { Python: 2 }],
  [/shopify|webflow/i, { Liquid: 3, JavaScript: 2, CSS: 2 }],
  [/scss|sass/i, { SCSS: 2 }],
  [/javascript|es6|es5/i, { JavaScript: 2 }],
  [/typescript/i, { TypeScript: 3 }],
  [/mysql|sql/i, { SQL: 1 }],
];

export function languageMix(input: { measured?: { name: string; bytes: number }[]; technologies: string[] }): {
  items: LanguageShare[];
  measured: boolean;
} {
  if (input.measured?.length) {
    const total = input.measured.reduce((sum, item) => sum + item.bytes, 0);
    return {
      measured: true,
      items: input.measured.map((item) => ({ name: item.name, share: item.bytes / total, color: COLORS[item.name] ?? '#888' })),
    };
  }
  const weights: Record<string, number> = {};
  const blob = input.technologies.join(' ');
  for (const [pattern, mix] of INFER) {
    if (!pattern.test(blob)) continue;
    for (const [name, weight] of Object.entries(mix)) weights[name] = (weights[name] ?? 0) + weight;
  }
  if (!Object.keys(weights).length) Object.assign(weights, { HTML: 2, CSS: 2, JavaScript: 2 });
  const total = Object.values(weights).reduce((a, b) => a + b, 0);
  return {
    measured: false,
    items: Object.entries(weights)
      .map(([name, weight]) => ({ name, share: weight / total, color: COLORS[name] ?? '#888' }))
      .sort((a, b) => b.share - a.share),
  };
}

function seeded(seed: string): () => number {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) h = Math.imul(h ^ seed.charCodeAt(i), 16777619);
  let a = h >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export type Token = { x: number; w: number; color: string };

// Rows of tokens. Each row picks a language by share, indents like code,
// and splits into a few token widths.
export function minimap(seed: string, mix: LanguageShare[], rows = 46): Token[][] {
  const rand = seeded(seed);
  const pick = () => {
    let r = rand();
    for (const item of mix) {
      r -= item.share;
      if (r <= 0) return item.color;
    }
    return mix[0]?.color ?? '#888';
  };
  let indent = 0;
  const out: Token[][] = [];
  for (let i = 0; i < rows; i++) {
    if (rand() < 0.12) {
      out.push([]);
      continue;
    }
    const change = rand();
    if (change < 0.22 && indent < 4) indent++;
    else if (change > 0.78 && indent > 0) indent--;
    const color = pick();
    const tokens: Token[] = [];
    let x = indent * 4;
    const count = 1 + Math.floor(rand() * 4);
    for (let t = 0; t < count && x < 96; t++) {
      const w = 3 + Math.floor(rand() * 16);
      tokens.push({ x, w: Math.min(w, 100 - x), color: t === 0 || rand() > 0.5 ? color : pick() });
      x += w + 1.5;
    }
    out.push(tokens);
  }
  return out;
}

export function codeGraphSvg(seed: string, mix: LanguageShare[], rows = 46, className = ''): string {
  // One path per colour, one "M x y h w" per token: far smaller than a rect per token.
  const lines = minimap(seed, mix, rows);
  const height = rows * 3;
  const byColor = new Map<string, string[]>();
  for (const copy of [0, 1])
    lines.forEach((tokens, row) => {
      for (const t of tokens) {
        const d = `M${Math.round(t.x + 0.8)} ${row * 3 + copy * height + 1}h${Math.max(0, Math.round(t.w - 1.6))}`;
        if (!byColor.has(t.color)) byColor.set(t.color, []);
        byColor.get(t.color)!.push(d);
      }
    });
  const paths = [...byColor].map(([color, ds]) => `<path stroke="${color}" d="${ds.join('')}"/>`).join('');
  return `<svg class="codegraph ${className}" viewBox="0 0 100 ${height}" preserveAspectRatio="none" aria-hidden="true"><g class="codegraph__scroll" fill="none" stroke-width="1.6" stroke-linecap="round">${paths}</g></svg>`;
}

// 3D head generated from the headshot (research/portrait/make5.py): rows x cols of [depth, brightness, inside], base64.
export const HEAD = {"rows":112,"cols":96,"aspect":1.1074,"data":""};

// ---------------------------------------------------------------------------
// Builds: a device (browser, iPhone, Android) drawing a generated layout.
// Seeded, so a post always gets the same build. `variants` > 1 renders several
// layouts for the same device(s); the component cycles through them.

export type BuildMark = { d: string; cls: string; delay: number };
export type BuildDevice = { kind: 'browser' | 'iphone' | 'android'; chrome: BuildMark[]; layouts: BuildMark[][] };
export type Build = { viewBox: string; devices: BuildDevice[] };

type Rect = { x: number; y: number; w: number; h: number };
type Rand = () => number;

const r1 = (n: number) => Math.round(n * 10) / 10;

function rectPath(x: number, y: number, w: number, h: number, r = 0): string {
  if (r <= 0) return `M${r1(x)} ${r1(y)}h${r1(w)}v${r1(h)}h${r1(-w)}Z`;
  const k = Math.min(r, w / 2, h / 2);
  return `M${r1(x + k)} ${r1(y)}H${r1(x + w - k)}A${k} ${k} 0 0 1 ${r1(x + w)} ${r1(y + k)}V${r1(y + h - k)}A${k} ${k} 0 0 1 ${r1(x + w - k)} ${r1(y + h)}H${r1(x + k)}A${k} ${k} 0 0 1 ${r1(x)} ${r1(y + h - k)}V${r1(y + k)}A${k} ${k} 0 0 1 ${r1(x + k)} ${r1(y)}Z`;
}
const linePath = (x1: number, y1: number, x2: number, y2: number) => `M${r1(x1)} ${r1(y1)}L${r1(x2)} ${r1(y2)}`;
const circlePath = (cx: number, cy: number, r: number) =>
  `M${r1(cx - r)} ${r1(cy)}a${r} ${r} 0 1 0 ${r * 2} 0a${r} ${r} 0 1 0 ${-r * 2} 0`;

/** Collects marks in drawing order; delays are assigned at the end. */
class Pen {
  marks: { d: string; cls: string }[] = [];
  add(d: string, cls: string) { this.marks.push({ d, cls }); }
  rect(x: number, y: number, w: number, h: number, cls = 'b-ui', r = 2) { this.add(rectPath(x, y, w, h, r), cls); }
  text(x: number, y: number, w: number, cls = 'b-text') { this.add(linePath(x, y, x + Math.max(4, w), y), cls); }
  lines(x: number, y: number, w: number, n: number, gap: number, rand: Rand, cls = 'b-text') {
    for (let i = 0; i < n; i++) this.text(x, y + i * gap, i === n - 1 ? w * (0.4 + rand() * 0.4) : w * (0.82 + rand() * 0.18), cls);
  }
  image(x: number, y: number, w: number, h: number, cls = 'b-img') {
    this.add(rectPath(x, y, w, h, 2), cls);
    const s = Math.min(w, h);
    this.add(`M${r1(x + w * 0.12)} ${r1(y + h * 0.82)}L${r1(x + w * 0.38)} ${r1(y + h * 0.48)}L${r1(x + w * 0.56)} ${r1(y + h * 0.68)}L${r1(x + w * 0.7)} ${r1(y + h * 0.56)}L${r1(x + w * 0.88)} ${r1(y + h * 0.82)}`, cls);
    this.add(circlePath(x + w * 0.74, y + h * 0.3, Math.max(1.5, s * 0.08)), cls);
  }
  button(x: number, y: number, w: number, h: number, accent = false) {
    this.add(rectPath(x, y, w, h, h / 2), accent ? 'b-accent' : 'b-ui');
    this.text(x + w * 0.25, y + h / 2, w * 0.5, accent ? 'b-accent-text' : 'b-text');
  }
  dot(cx: number, cy: number, r: number, cls = 'b-ui') { this.add(circlePath(cx, cy, r), cls); }
  done(start = 300, step = 55): BuildMark[] {
    return this.marks.map((m, i) => ({ ...m, delay: start + Math.min(i * step, 2600) }));
  }
}

// ---------- Web layouts (content box inside the browser) ----------

function webNav(p: Pen, b: Rect, rand: Rand): number {
  p.rect(b.x, b.y + 2, 14, 10, 'b-ui', 2);
  const links = 3 + Math.floor(rand() * 2);
  for (let i = 0; i < links; i++) p.text(b.x + b.w - 70 - i * 26, b.y + 7, 16);
  p.button(b.x + b.w - 40, b.y + 1, 40, 12, true);
  return b.y + 24;
}

const WEB: ((p: Pen, b: Rect, rand: Rand) => void)[] = [
  // Landing: hero, image, three features
  (p, b, rand) => {
    let y = webNav(p, b, rand);
    const half = b.w * 0.48;
    p.text(b.x, y + 10, half * 0.95, 'b-head');
    p.text(b.x, y + 22, half * 0.7, 'b-head');
    p.lines(b.x, y + 38, half * 0.9, 3, 8, rand);
    p.button(b.x, y + 66, 46, 13, true);
    p.button(b.x + 52, y + 66, 46, 13);
    p.image(b.x + b.w * 0.54, y, b.w * 0.46, 84);
    y += 98;
    const cw = (b.w - 16) / 3;
    for (let i = 0; i < 3; i++) {
      const x = b.x + i * (cw + 8);
      p.rect(x, y, cw, b.y + b.h - y, 'b-ui', 3);
      p.dot(x + 12, y + 12, 5);
      p.lines(x + 8, y + 28, cw - 16, 3, 7, rand);
    }
  },
  // Article: wide image, title, column of text, sidebar
  (p, b, rand) => {
    let y = webNav(p, b, rand);
    p.image(b.x, y, b.w, 74);
    y += 86;
    const col = b.w * 0.66;
    p.text(b.x, y, col * 0.8, 'b-head');
    p.lines(b.x, y + 14, col, Math.max(3, Math.floor((b.y + b.h - y - 14) / 8)), 8, rand);
    const sx = b.x + col + 14;
    const sw = b.w - col - 14;
    p.rect(sx, y - 4, sw, 40, 'b-ui', 3);
    p.lines(sx + 8, y + 8, sw - 16, 3, 8, rand);
    p.button(sx, y + 44, sw, 13, true);
  },
  // Dashboard: sidebar, stat tiles, chart, rows
  (p, b, rand) => {
    const sw = b.w * 0.2;
    p.rect(b.x, b.y, sw, b.h, 'b-ui', 3);
    p.rect(b.x + 8, b.y + 8, 12, 9, 'b-ui', 2);
    for (let i = 0; i < 6; i++) p.text(b.x + 8, b.y + 30 + i * 13, sw - 20, i === 1 ? 'b-accent-text' : 'b-text');
    const x = b.x + sw + 10;
    const w = b.w - sw - 10;
    const tw = (w - 16) / 3;
    for (let i = 0; i < 3; i++) {
      p.rect(x + i * (tw + 8), b.y, tw, 34, 'b-ui', 3);
      p.text(x + i * (tw + 8) + 8, b.y + 12, tw * 0.4);
      p.text(x + i * (tw + 8) + 8, b.y + 24, tw * 0.6, 'b-head');
    }
    const cy = b.y + 44;
    const ch = 70;
    p.rect(x, cy, w, ch, 'b-ui', 3);
    let d = `M${r1(x + 8)} ${r1(cy + ch - 12)}`;
    const steps = 9;
    for (let i = 1; i <= steps; i++) d += `L${r1(x + 8 + (i / steps) * (w - 16))} ${r1(cy + 12 + rand() * (ch - 28))}`;
    p.add(d, 'b-accent-line');
    let ry = cy + ch + 12;
    while (ry < b.y + b.h - 6) {
      p.dot(x + 6, ry, 3.5);
      p.text(x + 16, ry, w * 0.4);
      p.text(x + w * 0.66, ry, w * 0.2);
      ry += 13;
    }
  },
  // Shop grid: chips, products
  (p, b, rand) => {
    let y = webNav(p, b, rand);
    for (let i = 0, x = b.x; i < 5; i++) {
      const w = 26 + rand() * 14;
      p.add(rectPath(x, y, w, 11, 5.5), i === 0 ? 'b-accent' : 'b-ui');
      x += w + 6;
    }
    y += 20;
    const cols = 4;
    const cw = (b.w - (cols - 1) * 8) / cols;
    const ch = (b.y + b.h - y - 8) / 2;
    for (let r = 0; r < 2; r++)
      for (let c = 0; c < cols; c++) {
        const x = b.x + c * (cw + 8);
        const yy = y + r * (ch + 8);
        p.image(x, yy, cw, ch - 20);
        p.text(x, yy + ch - 12, cw * 0.7);
        p.text(x, yy + ch - 4, cw * 0.3, 'b-head');
      }
  },
  // Pricing: centred title, three plans
  (p, b, rand) => {
    let y = webNav(p, b, rand);
    p.text(b.x + b.w * 0.3, y + 8, b.w * 0.4, 'b-head');
    p.text(b.x + b.w * 0.36, y + 20, b.w * 0.28);
    y += 32;
    const cw = (b.w - 20) / 3;
    for (let i = 0; i < 3; i++) {
      const x = b.x + i * (cw + 10);
      const lit = i === 1;
      p.rect(x, y, cw, b.y + b.h - y, lit ? 'b-accent' : 'b-ui', 4);
      p.text(x + 10, y + 14, cw * 0.4);
      p.text(x + 10, y + 30, cw * 0.5, 'b-head');
      p.lines(x + 10, y + 46, cw - 20, 5, 9, rand);
      p.button(x + 10, b.y + b.h - 22, cw - 20, 13, lit);
    }
  },
  // Portfolio: masonry
  (p, b, rand) => {
    let y = webNav(p, b, rand);
    p.text(b.x, y + 8, b.w * 0.35, 'b-head');
    y += 20;
    const cols = 3;
    const cw = (b.w - 16) / cols;
    for (let c = 0; c < cols; c++) {
      let yy = y;
      while (yy < b.y + b.h - 20) {
        const h = Math.min(b.y + b.h - yy, 30 + rand() * 46);
        if (h < 18) break;
        p.image(b.x + c * (cw + 8), yy, cw, h);
        yy += h + 8;
      }
    }
  },
];

// ---------- Phone layouts (content box inside the screen) ----------

function tabBar(p: Pen, b: Rect, n = 4): number {
  const y = b.y + b.h - 12;
  p.add(linePath(b.x - 6, y - 10, b.x + b.w + 6, y - 10), 'b-ui');
  for (let i = 0; i < n; i++) p.dot(b.x + ((i + 0.5) * b.w) / n, y, 4, i === 0 ? 'b-accent' : 'b-ui');
  return y - 16;
}

const PHONE: ((p: Pen, b: Rect, rand: Rand) => void)[] = [
  // Feed: title, search, chips, cards, tab bar
  (p, b, rand) => {
    const end = tabBar(p, b);
    p.text(b.x, b.y + 8, b.w * 0.45, 'b-head');
    p.dot(b.x + b.w - 7, b.y + 7, 7);
    p.add(rectPath(b.x, b.y + 22, b.w, 14, 7), 'b-ui');
    for (let i = 0, x = b.x; i < 3; i++) {
      const w = 26 + rand() * 10;
      p.add(rectPath(x, b.y + 44, w, 10, 5), i === 0 ? 'b-accent' : 'b-ui');
      x += w + 5;
    }
    let y = b.y + 64;
    while (y + 70 < end) {
      p.image(b.x, y, b.w, 46);
      p.text(b.x, y + 56, b.w * 0.7, 'b-head');
      p.text(b.x, y + 66, b.w * 0.45);
      y += 80;
    }
  },
  // Settings list: grouped rows with icons and chevrons
  (p, b, rand) => {
    p.text(b.x, b.y + 10, b.w * 0.5, 'b-head');
    let y = b.y + 28;
    for (let g = 0; g < 3 && y < b.y + b.h - 30; g++) {
      const rows = 2 + Math.floor(rand() * 2);
      p.rect(b.x, y, b.w, rows * 18, 'b-ui', 5);
      for (let i = 0; i < rows; i++) {
        const cy = y + 9 + i * 18;
        p.add(rectPath(b.x + 6, cy - 5, 10, 10, 3), g === 0 && i === 0 ? 'b-accent' : 'b-ui');
        p.text(b.x + 22, cy, b.w * 0.45);
        p.add(`M${r1(b.x + b.w - 10)} ${r1(cy - 3)}l3 3l-3 3`, 'b-ui');
      }
      y += rows * 18 + 12;
    }
  },
  // Mobile web: hamburger, hero, button, image, cards
  (p, b, rand) => {
    p.rect(b.x, b.y, 12, 9, 'b-ui', 2);
    for (let i = 0; i < 3; i++) p.text(b.x + b.w - 12, b.y + 1 + i * 3.5, 12, 'b-thin');
    p.text(b.x, b.y + 26, b.w * 0.9, 'b-head');
    p.text(b.x, b.y + 38, b.w * 0.6, 'b-head');
    p.lines(b.x, b.y + 52, b.w, 3, 8, rand);
    p.button(b.x, b.y + 76, b.w, 14, true);
    p.image(b.x, b.y + 98, b.w, 60);
    let y = b.y + 168;
    while (y + 34 < b.y + b.h) {
      p.rect(b.x, y, b.w, 28, 'b-ui', 4);
      p.lines(b.x + 8, y + 10, b.w - 16, 2, 8, rand);
      y += 36;
    }
  },
  // Chat: header, bubbles, input
  (p, b, rand) => {
    p.dot(b.x + 7, b.y + 7, 7);
    p.text(b.x + 20, b.y + 7, b.w * 0.4, 'b-head');
    p.add(linePath(b.x - 6, b.y + 20, b.x + b.w + 6, b.y + 20), 'b-ui');
    let y = b.y + 30;
    let i = 0;
    while (y + 40 < b.y + b.h) {
      const mine = i % 2 === 1;
      const w = b.w * (0.45 + rand() * 0.3);
      const h = 14 + Math.floor(rand() * 2) * 9;
      p.add(rectPath(mine ? b.x + b.w - w : b.x, y, w, h, 7), mine ? 'b-accent' : 'b-ui');
      y += h + 8;
      i++;
    }
    p.add(rectPath(b.x, b.y + b.h - 16, b.w - 20, 14, 7), 'b-ui');
    p.dot(b.x + b.w - 7, b.y + b.h - 9, 7, 'b-accent');
  },
  // Wallet: balance, chart, transactions, tab bar
  (p, b, rand) => {
    const end = tabBar(p, b);
    p.text(b.x, b.y + 6, b.w * 0.3);
    p.text(b.x, b.y + 20, b.w * 0.6, 'b-head');
    let d = `M${r1(b.x)} ${r1(b.y + 74)}`;
    for (let i = 1; i <= 8; i++) d += `L${r1(b.x + (i / 8) * b.w)} ${r1(b.y + 40 + rand() * 34)}`;
    p.add(d, 'b-accent-line');
    let y = b.y + 92;
    while (y + 18 < end) {
      p.add(rectPath(b.x, y - 6, 12, 12, 4), 'b-ui');
      p.text(b.x + 18, y, b.w * 0.4);
      p.text(b.x + b.w - 22, y, 22, 'b-head');
      y += 20;
    }
  },
];

// ---------- Devices ----------

function browser(x: number, y: number, w: number, h: number): { chrome: Pen; box: Rect } {
  const c = new Pen();
  c.add(rectPath(x, y, w, h, 6), 'b-body');
  c.add(linePath(x, y + 18, x + w, y + 18), 'b-frame');
  for (let i = 0; i < 3; i++) c.dot(x + 10 + i * 8, y + 9, 2.4, 'b-frame');
  c.add(rectPath(x + w * 0.3, y + 4.5, w * 0.4, 9, 4.5), 'b-ui');
  c.add(linePath(x + w * 0.3 + 4, y + 17.6, x + w * 0.7 - 4, y + 17.6), 'b-load');
  return { chrome: c, box: { x: x + 12, y: y + 28, w: w - 24, h: h - 38 } };
}

function phone(x: number, y: number, w: number, h: number, kind: 'iphone' | 'android'): { chrome: Pen; box: Rect } {
  const c = new Pen();
  const r = kind === 'iphone' ? w * 0.17 : w * 0.1;
  // An opaque screen that hides whatever sits behind the phone, drawn first.
  c.add(rectPath(x, y, w, h, r), 'b-occlude');
  c.add(rectPath(x, y, w, h, r), 'b-body');
  if (kind === 'iphone') {
    c.add(rectPath(x + w / 2 - w * 0.16, y + 8, w * 0.32, 9, 4.5), 'b-frame');
    c.add(linePath(x + w / 2 - w * 0.17, y + h - 7, x + w / 2 + w * 0.17, y + h - 7), 'b-frame');
  } else {
    c.dot(x + w / 2, y + 12, 3.2, 'b-frame');
    c.add(linePath(x + w / 2 - w * 0.12, y + h - 8, x + w / 2 + w * 0.12, y + h - 8), 'b-frame');
  }
  const top = kind === 'iphone' ? 28 : 26;
  return { chrome: c, box: { x: x + 12, y: y + top, w: w - 24, h: h - top - 18 } };
}

function pick<T>(list: T[], rand: Rand): T {
  return list[Math.floor(rand() * list.length)];
}

function layouts(fns: ((p: Pen, b: Rect, rand: Rand) => void)[], box: Rect, rand: Rand, n: number, start: number): BuildMark[][] {
  const order = [...fns.keys()].sort(() => rand() - 0.5);
  const out: BuildMark[][] = [];
  for (let i = 0; i < n; i++) {
    const p = new Pen();
    fns[order[i % order.length]](p, box, rand);
    out.push(p.done(start));
  }
  return out;
}

/**
 * A device drawing a generated layout. With `pair`, a browser and a phone build
 * side by side (the responsive story); otherwise the seed picks one device.
 */
export function build(seed: string, options: { variants?: number; pair?: boolean } = {}): Build {
  const rand = random(hash(seed));
  const variants = Math.max(1, options.variants ?? 1);
  if (options.pair) {
    const b = browser(4, 24, 400, 270);
    const kind = rand() > 0.5 ? 'iphone' : 'android';
    const ph = phone(352, 100, 132, 264, kind);
    return {
      viewBox: '0 0 490 372',
      devices: [
        { kind: 'browser', chrome: b.chrome.done(0, 70), layouts: layouts(WEB, b.box, rand, variants, 600) },
        { kind, chrome: ph.chrome.done(400, 70), layouts: layouts(PHONE, ph.box, rand, variants, 1000) },
      ],
    };
  }
  const roll = rand();
  if (roll < 0.55) {
    const b = browser(8, 8, 384, 234);
    return { viewBox: '0 0 400 250', devices: [{ kind: 'browser', chrome: b.chrome.done(0, 70), layouts: layouts(WEB, b.box, rand, variants, 500) }] };
  }
  const kind = roll < 0.78 ? 'iphone' : 'android';
  // Two phones, offset: the same app on two screens.
  const a = phone(118, 6, 116, 236, kind);
  const c = phone(244, 26, 116, 236, kind === 'iphone' ? 'android' : 'iphone');
  return {
    viewBox: '0 0 400 270',
    devices: [
      { kind, chrome: a.chrome.done(0, 70), layouts: layouts(PHONE, a.box, rand, variants, 500) },
      { kind: kind === 'iphone' ? 'android' : 'iphone', chrome: c.chrome.done(300, 70), layouts: layouts(PHONE, c.box, rand, variants, 900) },
    ],
  };
}
